using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- CalculateTotal: DataRow-driven tests ---

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "Two items, no tax")]
    [DataRow(10.00, 1, 0.10, 11.00, DisplayName = "Single item, 10% tax")]
    [DataRow(25.50, 3, 0.08, 82.62, DisplayName = "Multiple items, 8% tax")]
    [DataRow(0.00, 5, 0.20, 0.00, DisplayName = "Zero price, any quantity")]
    [DataRow(99.99, 0, 0.15, 0.00, DisplayName = "Zero quantity returns zero")]
    [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expectedTotal)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expectedTotal, result, $"Expected {expectedTotal} for unitPrice={unitPrice}, qty={quantity}, tax={taxRate}");
    }

    [TestMethod]
    [DataRow(-1.00, 1, 0.10, DisplayName = "Negative unit price throws")]
    public void CalculateTotal_NegativeUnitPrice_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, -1, 0.10, DisplayName = "Negative quantity throws")]
    public void CalculateTotal_NegativeQuantity_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.00, 1, -0.01, DisplayName = "Tax rate below 0 throws")]
    [DataRow(10.00, 1, 1.01, DisplayName = "Tax rate above 1 throws")]
    public void CalculateTotal_InvalidTaxRate_Throws(double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // --- ApplyDiscount: DynamicData-driven tests ---

    public static IEnumerable<object[]> ApplyDiscountTestData
    {
        get
        {
            yield return new object[] { 100.00m, 0m, 100.00m };   // No discount
            yield return new object[] { 100.00m, 10m, 90.00m };   // 10% off
            yield return new object[] { 100.00m, 50m, 50.00m };   // 50% off
            yield return new object[] { 100.00m, 100m, 0.00m };   // 100% off (free)
            yield return new object[] { 49.99m, 25m, 37.4925m };  // Fractional result
            yield return new object[] { 0.00m, 50m, 0.00m };      // Zero price stays zero
            yield return new object[] { 200.00m, 33.33m, 133.34m }; // Repeating discount
        }
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expectedPrice)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expectedPrice, result,
            $"Expected {expectedPrice} after {discountPercent}% discount on {price}");
    }

    // DynamicData from a method (demonstrates the method-based overload)
    public static IEnumerable<object[]> InvalidDiscountData()
    {
        yield return new object[] { 100.00m, -1m };    // Negative discount
        yield return new object[] { 100.00m, 100.01m }; // Over 100%
        yield return new object[] { 50.00m, -50m };    // Large negative
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData), DynamicDataSourceType.Method)]
    public void ApplyDiscount_InvalidDiscountPercent_Throws(decimal price, decimal discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }
}

